<template><div><div class="page-head"><div><h2>交易中心</h2><p>查询订单、支付状态与平台收入</p></div><el-select v-model="status" clearable placeholder="全部状态" @change="load"><el-option v-for="(v,k) in labels" :key="k" :label="v" :value="Number(k)" /></el-select></div>
<el-row :gutter="16" class="metrics"><el-col v-for="m in metrics" :key="m.label" :span="6"><el-card shadow="never"><small>{{m.label}}</small><strong>{{m.value}}</strong></el-card></el-col></el-row>
<el-card shadow="never"><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="orderNo" label="订单号" min-width="190"/><el-table-column prop="username" label="用户" width="110"/><el-table-column prop="courseTitle" label="课程" min-width="180"/><el-table-column label="金额" width="100"><template #default="{row}">¥{{row.amount}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="types[row.status]">{{labels[row.status]}}</el-tag></template></el-table-column><el-table-column prop="payMethod" label="支付方式" width="100"/><el-table-column prop="createdAt" label="创建时间" width="180"/></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="10" layout="total,prev,pager,next" @current-change="load"/></el-card></div></template>
<script setup>import {ref,onMounted,computed} from 'vue';import {adminApi} from '@/api/admin';const rows=ref([]),total=ref(0),page=ref(1),status=ref(),loading=ref(false),stats=ref({});const labels={0:'待支付',1:'已支付',2:'已取消',3:'已退款'},types={0:'warning',1:'success',2:'info',3:'danger'};const metrics=computed(()=>[{label:'订单总量',value:stats.value.totalOrders||0},{label:'已支付订单',value:stats.value.paidOrders||0},{label:'平台收入',value:`¥${stats.value.totalRevenue||0}`},{label:'支付成功率',value:stats.value.totalOrders?`${Math.round((stats.value.paidOrders||0)/stats.value.totalOrders*100)}%`:'0%'}]);async function load(){loading.value=true;try{const r=await adminApi.getOrders({page:page.value,size:10,status:status.value});rows.value=r.data?.records||[];total.value=r.data?.total||0}catch{}finally{loading.value=false}}onMounted(async()=>{const r=await adminApi.getStats();stats.value=r.data||{};load()})</script>
<style scoped>.page-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.page-head h2{margin:0}.page-head p,small{color:#909399}.metrics{margin-bottom:18px}.metrics strong{display:block;font-size:26px;margin-top:8px}.el-pagination{justify-content:flex-end;margin-top:16px}</style>
